CREATE TABLE public.watchlist_entries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, ticker text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,ticker));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.watchlist_entries TO authenticated;
GRANT ALL ON public.watchlist_entries TO service_role;
ALTER TABLE public.watchlist_entries ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_watchlist ON public.watchlist_entries FOR ALL TO authenticated USING (user_id = (select auth.uid())) WITH CHECK (user_id = (select auth.uid()));
CREATE TABLE public.portfolio_holdings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, ticker text NOT NULL, shares numeric NOT NULL CHECK(shares > 0), cost_basis numeric NOT NULL CHECK(cost_basis > 0), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,ticker));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.portfolio_holdings TO authenticated;
GRANT ALL ON public.portfolio_holdings TO service_role;
ALTER TABLE public.portfolio_holdings ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_holdings ON public.portfolio_holdings FOR ALL TO authenticated USING (user_id = (select auth.uid())) WITH CHECK (user_id = (select auth.uid()));